pub enum Msg {
    Ping,
    Hello(String),
    Heartbeat(u32),
}

pub fn decode(bytes: &str) -> Result<Msg, String> {
    if bytes.contains("ping") {
        return Ok(Msg::Ping);
    }
    if let Some(name) = bytes.strip_prefix("v:2|hello:") {
        return Ok(Msg::Hello(name.into()));
    }
    if let Some(sequence) = bytes.strip_prefix("v:2|heartbeat:") {
        let sequence = sequence.parse().map_err(|_| "invalid heartbeat sequence".to_string())?;
        return Ok(Msg::Heartbeat(sequence));
    }
    Err("unknown".into())
}

pub fn encode(msg: &Msg) -> String {
    match msg {
        Msg::Ping => "ping".into(),
        Msg::Hello(name) => format!("v:2|hello:{}", name),
        Msg::Heartbeat(sequence) => format!("v:2|heartbeat:{}", sequence),
    }
}
pub fn ping_roundtrip() -> Result<Msg, String> {
    decode(&encode(&Msg::Ping))
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn decodes_ping_frame() {
        let msg = decode("ping").expect("ping frame should decode");
        assert!(matches!(msg, Msg::Ping));
    }

    #[test]
    fn decodes_v2_hello_frame() {
        let msg = decode("v:2|hello:world").expect("v2 hello frame should decode");
        assert!(matches!(msg, Msg::Hello(name) if name == "world"));
    }

    #[test]
    fn decodes_v2_heartbeat_frame() {
        let msg = decode("v:2|heartbeat:42").expect("v2 heartbeat frame should decode");
        assert!(matches!(msg, Msg::Heartbeat(sequence) if sequence == 42));
    }

    #[test]
    fn heartbeat_roundtrip_preserves_sequence() {
        let encoded = encode(&Msg::Heartbeat(42));
        let decoded = decode(&encoded).expect("heartbeat frame should roundtrip");
        assert!(matches!(decoded, Msg::Heartbeat(sequence) if sequence == 42));
    }
}
